(function(root){
function scan(data,width,height,limit=20){const pixels=new Uint8ClampedArray(data),found=[],seen=new Set();for(let i=0;i<limit;i++){let qr=jsQR(pixels,width,height,{inversionAttempts:'attemptBoth'});if(!qr){for(const[tw,th]of [[Math.ceil(width*.6),height],[width,Math.ceil(height*.6)],[Math.ceil(width*.6),Math.ceil(height*.6)]]){for(const oy of [0,height-th]){for(const ox of [0,width-tw]){const tile=new Uint8ClampedArray(tw*th*4);for(let y=0;y<th;y++)tile.set(pixels.subarray(((y+oy)*width+ox)*4,((y+oy)*width+ox+tw)*4),y*tw*4);const hit=jsQR(tile,tw,th,{inversionAttempts:'attemptBoth'});if(hit){for(const pt of Object.values(hit.location))if(pt&&Number.isFinite(pt.x)){pt.x+=ox;pt.y+=oy}qr=hit;break}}if(qr)break}if(qr)break}}if(!qr)break;if(!seen.has(qr.data)){seen.add(qr.data);found.push(qr.data)}const pts=Object.values(qr.location).filter(v=>v&&Number.isFinite(v.x)&&Number.isFinite(v.y));const left=Math.max(0,Math.floor(Math.min(...pts.map(p=>p.x)))-4),right=Math.min(width,Math.ceil(Math.max(...pts.map(p=>p.x)))+4),top=Math.max(0,Math.floor(Math.min(...pts.map(p=>p.y)))-4),bottom=Math.min(height,Math.ceil(Math.max(...pts.map(p=>p.y)))+4);for(let y=top;y<bottom;y++)for(let x=left;x<right;x++){const n=(y*width+x)*4;pixels[n]=pixels[n+1]=pixels[n+2]=pixels[n+3]=255}}return found}
function read(data,width,height,p){return new Promise((resolve,reject)=>{const worker=new Worker('qr-worker.js?v=20261020');let timer;const stop=()=>{worker.terminate();clearTimeout(timer);p.cancel=null};p.cancel=()=>{stop();reject(Error('Đã dừng đọc QR.'));return true};timer=setTimeout(()=>{stop();reject(Error('Ảnh quá phức tạp. Hãy cắt riêng từng vùng QR và thử lại.'))},15000);worker.onerror=()=>{stop();reject(Error('Không khởi động được bộ đọc QR.'))};worker.onmessage=e=>{stop();e.data.ok?resolve(e.data.result):reject(Error(e.data.error))};worker.postMessage({data,width,height})})}root.ToolHubQRReader={scan,read};
})(globalThis);
